def r(s, k):
    count = {}
    left = top = best = 0
    for right in range(len(s)):
        count[s[right]] = count.get(s[right], 0) + 1
        top = max(top, count[s[right]])
        while (right - left + 1) - top > k:
            count[s[left]] -= 1
            left += 1
        best = max(best, right - left + 1)
    return best

