def split(nums):
    t = sum(nums)
    if t % 2 == 1:
        return False
    t //= 2
    ok = [False] * (t + 1)
    ok[0] = True
    for x in nums:
        for s in range(x, t + 1):
            ok[s] = ok[s] or ok[s - x]
    return ok[t]

code.cpp:
bool split(vector<int> nums) {
    int t = accumulate(nums.begin(), nums.end(), 0);
    if (t % 2 == 1)
        return false;
    t /= 2;
    vector<bool> ok(t + 1, false);
    ok[0] = true;
    for (int x : nums)
        for (int s = x; s <= t; s++)
            ok[s] = ok[s] || ok[s - x];
    return ok[t];
}

