static boolean split(int[] nums) {
    int t = Arrays.stream(nums).sum();
    if (t % 2 == 1)
        return false;
    t /= 2;
    boolean[] ok = new boolean[t + 1];
    ok[0] = true;
    for (int x : nums)
        for (int s = x; s <= t; s++)
            ok[s] = ok[s] || ok[s - x];
    return ok[t];
}
